package com.gathin.tvhome;
import android.app.*;import android.os.*;import android.widget.*;import java.util.*;
/** Styled paired-computer management; native pairing stays Android-owned. */
final class SessionDebugUi {
 private static AlertDialog active;
 static void close(){AlertDialog dialog=active;if(dialog!=null)dialog.dismiss();}
 static void pair(Activity a){if(!SessionSettingsUi.ready(a))return;close();TextView text=new TextView(a);text.setText("Starting Android pairing...");text.setTextColor(0xfff5f5fa);text.setTextSize(23);text.setPadding(32,24,32,24);text.setTypeface(UiFont.get(a,R.string.font_regular));AlertDialog dialog=new SettingsPopup.Builder(a).setTitle("Pair computer").setView(text).setNegativeButton("Close",null).create();active=dialog;boolean[] dismissed={false};Handler handler=new Handler(Looper.getMainLooper());java.util.function.Consumer<Bundle> display=state->{if(dismissed[0]||a.isFinishing()||a.isDestroyed())return;if(state.getBoolean("expired")){text.setText("Pairing expired. Close and open this window again.");return;}if(state.getBoolean("failed")){text.setText("Android pairing service could not be resolved. Close and try again when the network is ready.");return;}int port=state.getInt("port");text.setText(port==0?"Waiting for Android pairing service...":"Pairing code: "+state.getString("code")+"\nAddress: "+(state.getString("address").contains(":")?"["+state.getString("address")+"]":state.getString("address"))+":"+port+"\n\nOn the computer, use adb pair with this address. Keep this window open; close it after pairing completes. Expires in two minutes.");};
  Binder listener=new Binder(){@Override protected boolean onTransact(int code,Parcel data,Parcel reply,int flags)throws RemoteException{if(Binder.getCallingUid()!=2000)throw new SecurityException("Unknown pairing sender");if(code==FIRST_CALL_TRANSACTION){data.enforceInterface("com.gathin.tvhome.NativePairing.v1");Bundle state=data.readBundle(getClass().getClassLoader());if(state!=null)handler.post(()->display.accept(state));return true;}return super.onTransact(code,data,reply,flags);}};
  dialog.setOnDismissListener(d->{dismissed[0]=true;if(active==dialog)active=null;cancelPairing();});dialog.show();SettingsPopup.style(dialog);new Thread(()->{try{Bundle input=new Bundle();input.putBinder("listener",listener);Bundle state=SettingsSessionClient.call(SettingsSessionClient.PAIR_START,input);handler.post(()->{if(dismissed[0])cancelPairing();else display.accept(state);});}catch(Exception failure){handler.post(()->{if(!dismissed[0]){text.setText("Android pairing could not start.");SessionSettingsUi.error(a,failure);}});}},"native-pair-start").start();
 }
 private static void cancelPairing(){new Thread(()->{try{SettingsSessionClient.call(SettingsSessionClient.PAIR_STOP,new Bundle());}catch(Exception ignored){}},"native-pair-close").start();}
 static void devices(Activity a,Runnable refresh){if(!SessionSettingsUi.ready(a))return;SessionSettingsUi.read(a,SettingsSessionClient.ADB_READ,new Bundle(),state->{
  ArrayList<Bundle> devices=state.getParcelableArrayList("devices");if(devices==null)devices=new ArrayList<>();final ArrayList<Bundle> entries=devices;
  String[] names=new String[entries.size()];for(int i=0;i<names.length;i++)names[i]=entries.get(i).getString("name","Computer")+(entries.get(i).getBoolean("connected")?" (connected)":"");
  SettingsPopup.Builder b=new SettingsPopup.Builder(a);b.setTitle("Paired computers");if(names.length==0)b.setMessage("No paired computers.");else b.setItems(names,(dialog,w)->SessionSettingsUi.confirm(a,"Forget computer?","This removes its debugging authorisation and ends this helper session. Pair again to reconnect.",()->SessionSettingsUi.change(a,SettingsSessionClient.ADB_UNPAIR,SettingsSessionClient.input("key",entries.get(w).getString("key")),refresh)));
  AlertDialog d=b.setPositiveButton("Close",null).setNeutralButton("Revoke all authorisations",(dialog,w)->SessionSettingsUi.confirm(a,"Revoke all debugging authorisations?","All trusted computers will need authorisation again. The helper and computer connection will end.",()->SessionSettingsUi.change(a,SettingsSessionClient.ADB_CLEAR,new Bundle(),refresh))).create();d.show();SettingsPopup.style(d);
 });}
 private SessionDebugUi(){}
}
